    ("未収入金", "みしゅうにゅうきん", "mishuunyuukin", "khoản phải thu khác", "Tiền có quyền thu phát sinh từ các giao dịch bán tài sản không thuộc hàng hóa kinh doanh chính.", "Accounts receivable - other", "PRO-A1", 93, [("使わなくなった社用車を売却し、代金未回収分を未収入金とした。", "Bán xe công ty không dùng nữa và ghi số tiền chưa thu vào khoản phải thu khác.", "Sold an unused company car and recorded the uncollected balance as accounts receivable - other.")], [], ["未収入金を回収する", "資産売却代金"], ["未払金", "売掛金"]),
    ("短期貸付金", "たんきかしつけきん", "tankikashitsukekin", "cho vay ngắn hạn", "Khoản tiền doanh nghiệp cho công ty con, đối tác hoặc nhân viên vay với kỳ hạn thu hồi dưới 1 năm.", "Short-term loans receivable", "PRO-A2", 89, [("子会社の一時的な資金不足を補うため、短期貸付金を実行した。", "Cung cấp khoản cho vay ngắn hạn để bù đắp thiếu hụt dòng tiền tạm thời của công ty con.", "Executed short-term loans to cover the subsidiary's temporary cash shortage.")], [], ["短期貸付金利息", "貸付金残高"], ["長期貸付金", "受取利息"]),
    ("貸倒引当金", "かしだおれひきあてきん", "kashidaorehikiatekin", "dự phòng nợ phải thu khó đòi", "Khoản trích trước vào chi phí để bù đắp các khoản công nợ có khả năng bị thất thoát không thu hồi được.", "Allowance for doubtful accounts", "PRO-A2", 94, [("期末の売掛金残高に対して過去の実績率に基づき貸倒引当金を計上する。", "Trích lập dự phòng nợ khó đòi trên số dư nợ phải thu cuối kỳ dựa theo tỷ lệ tổn thất quá khứ.", "Recognize an allowance for doubtful accounts on year-end receivables based on historical default rates.")], [], ["引当金繰入", "個別評価引当金"], ["貸倒損失", "売掛金"]),
    ("立替金", "たてかえきん", "tatekaekin", "khoản chi hộ / ứng tiền trước", "Khoản tiền doanh nghiệp tạm thời chi trả hộ cho đối tác, khách hàng hoặc nhân viên và sẽ được thu lại sau.", "Advances paid / Claims for reimbursement", "PRO-A1", 92, [("出張者の旅費交通費を会社が一時的に立替金として処理した。", "Công ty tạm thời xử lý chi phí đi lại của người đi công tác dưới dạng tiền ứng trước chi hộ.", "The company temporarily processed the business traveler's transportation costs as advances paid.")], [], ["立替金を精算する", "立替払い"], ["預り金", "仮払金"]),
    ("仮払金", "かりばらいきん", "karibaraikin", "khoản tạm ứng", "Số tiền đã xuất quỹ đưa cho nhân viên nhưng chưa xác định được nội dung chi phí cụ thể hoặc số tiền chính xác.", "Suspense payments", "PRO-A1", 93, [("海外出張に行く営業担当者に概算で仮払金50万円を支給した。", "Cấp tạm ứng ước tính 50 vạn yên cho nhân viên kinh doanh đi công tác nước ngoài.", "Disbursed suspense payments of 500,000 yen as an estimate to the sales rep traveling abroad.")], [], ["仮払金を精算する", "仮払金残高"], ["仮受金", "立替金"]),
    ("未収収益", "みしゅうしゅうえき", "mishuushuueki", "doanh thu dồn tích / lãi dự thu", "Khoản doanh thu đã phát sinh từ dịch vụ cung cấp liên tục trong kỳ nhưng chưa đến kỳ hạn thu tiền theo hợp đồng.", "Accrued income", "PRO-A2", 89, [("定期預金の未収利息を決算日に未収収益として計上した。", "Hạch toán tiền lãi chưa thu của khoản tiết kiệm định kỳ vào doanh thu dồn tích tại ngày quyết toán.", "Recorded accrued interest on time deposits as accrued income on the closing date.")], [], ["未収利息", "経過勘定計上"], ["前受収益", "未払費用"]),
