    ("無形固定資産", "むけいこていしさん", "mukeikoteishisan", "tài sản cố định vô hình", "Tài sản dài hạn không có hình thái vật chất nhưng mang lại quyền lợi kinh tế pháp lý (như bằng sáng chế, phần mềm).", "Intangible assets", "PRO-A2", 93, [("無形固定資産は定額法によって耐用年数内で償却されます。", "Tài sản cố định vô hình được phân bổ khấu hao theo phương pháp đường thẳng trong thời gian sử dụng hữu ích.", "Intangible assets are amortized over their useful life using the straight-line method.")], [], ["無形資産の償却", "知的財産"], ["有形固定資産", "のれん", "ソフトウェア"]),
    ("のれん", "のれん", "noren", "lợi thế thương mại (goodwill)", "Phần chênh lệch trả cao hơn giá trị tài sản ròng khi mua lại sáp nhập một doanh nghiệp khác.", "Goodwill", "PRO-A2", 92, [("買収時に生じたのれんは20年以内の均等償却が日本基準で求められます。", "Chuẩn mực Nhật Bản yêu cầu phân bổ đều lợi thế thương mại phát sinh khi mua lại công ty trong vòng 20 năm.", "Under Japanese GAAP, goodwill arising from acquisitions must be amortized evenly within 20 years.")], [], ["のれん償却費", "のれん減損"], ["企業結合", "無形固定資産"]),
    ("特許権", "とっきょけん", "tokkyoken", "quyền sở hữu bằng sáng chế", "Quyền độc quyền khai thác sáng chế công nghệ đã được cơ quan sở hữu trí tuệ cấp bằng bảo hộ.", "Patent right", "PRO-A2", 90, [("自社開発した新技術の特許権を無形固定資産に計上した。", "Hạch toán quyền sáng chế công nghệ mới tự phát triển vào tài sản cố định vô hình.", "Recorded patent rights for internally developed new technology as intangible assets.")], [], ["特許権の取得", "特許料収入"], ["無形固定資産", "知的財産権"]),
    ("ソフトウェア", "そふとうぇあ", "sofutowea", "phần mềm máy tính", "Các phần mềm nghiệp vụ mua ngoài hoặc tự phát triển phục vụ hoạt động nội bộ công ty được vốn hóa làm tài sản.", "Software", "PRO-A1", 95, [("基幹業務システム用のソフトウェア開発費を資産計上する。", "Vốn hóa chi phí phát triển phần mềm hệ thống ERP thành tài sản.", "Capitalize development costs of core business software as an asset.")], [], ["自社利用ソフトウェア", "市場販売目的ソフトウェア"], ["無形固定資産", "減価償却費"]),
    ("借地権", "しゃくちけん", "shakuchiken", "quyền thuê đất dài hạn", "Quyền sử dụng đất của người khác để xây dựng công trình dựa trên hợp đồng thuê đất dài hạn.", "Right of leasehold", "PRO-A2", 87, [("借地権の対価として地主に支払った権利金を無形固定資産とする。", "Tiền quyền lợi thuê trả cho chủ đất để có quyền thuê đất được ghi nhận là tài sản cố định vô hình.", "The key money paid to landlords as consideration for leasehold rights is treated as intangible assets.")], [], ["借地権設定", "底地"], ["土地", "無形固定資産"]),
